class Employee:
    def __init__(self, name, salary):
        pass

question.solution:
class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def work(self):
        return '在做通用工作'

    def describe(self):
        return f'{self.name} 月薪 {self.salary}'


class Developer(Employee):
    def __init__(self, name, salary, language='Python'):
        super().__init__(name, salary)
        self.language = language

    def work(self):
        return f'在用 {self.language} 写代码'


class Manager(Employee):
    def __init__(self, name, salary, team_size=0):
        super().__init__(name, salary)
        self.team_size = team_size

    def work(self):
        return f'在管理 {self.team_size} 个人的团队'


staff = [Employee('老王', 8000), Developer('小明', 15000),
         Manager('小红', 20000, 5)]
for person in staff:
    print(person.describe(), '|', person.work())
